[归一化后的问题]
本月的 GMV 是多少？

[已审查的查询计划]
{
  "assets": [
    {
      "asset": "order_paid",
      "join_key": null
    }
  ],
  "blocking_issues": [],
  "dimensions": [],
  "filters": [
    "pay_status = 'paid'",
    "refund_status <> 'refunded'",
    "is_test_order = false",
    "pay_time 落在本月（relative:this_month）"
  ],
  "grain": "无分组（全量汇总，最细粒度=子订单 sub_order_id）",
  "limit": 1,
  "metrics": [
    {
      "caliber": "SUM(order_paid.pay_amount)；按支付完成时间 pay_time 统计；含运费；剔除全额退款订单；剔除测试单；不扣减部分退款。默认谓词：pay_status = 'paid'；refund_status <> 'refunded'；is_test_order = false",
      "name": "gmv"
    }
  ],
  "order_by": [],
  "output_columns": [
    "gmv"
  ],
  "time_range": {
    "end": null,
    "start": null
  }
}

