{
  "assets": [
    {
      "asset": "order_paid",
      "join_key": null
    }
  ],
  "blocking_issues": [],
  "dimensions": [],
  "filters": [
    "order_paid.pay_time 落在 relative:last_month 对应的自然月区间（上月 1 日 00:00:00 至上月最后一日 23:59:59）",
    "支付状态 pay_status = 'paid'",
    "退款状态 refund_status <> 'refunded'（剔除全额退款订单）",
    "is_test_order = false（剔除测试单）"
  ],
  "grain": "订单（子订单）级汇总，无分组，输出单行",
  "limit": 1,
  "metrics": [
    {
      "caliber": "gmv（GMV）：SUM(order_paid.pay_amount)，按支付完成时间 pay_time 统计；含运费、扣除优惠后金额；剔除全额退款订单与测试单；不扣减部分退款（部分退款按口径暂不扣减）；不做去重，直接对子订单实付金额求和",
      "name": "gmv"
    }
  ],
  "order_by": [],
  "output_columns": [
    "gmv"
  ],
  "time_range": {
    "end": "2025-09-30",
    "start": "2025-09-01"
  }
}

